open Prismel
type artifact={pieces:int;triangles:int;render_vertices:int;cook_seconds:float;cook_seconds_four:float;pack_seconds:float;topology_hash:string;attribute_hash:string;order_hash:string;render_hash:string;vertices:bytes;indices:bytes}
let putf bytes offset value=Bytes.set_int64_le bytes offset(Int64.bits_of_float value)
let pack(result:Shattered_acceptance.result) ~cook_seconds_four=
  let view=Mesh.Private.packed_view result.mesh and count=result.render_vertices in
  let vertices=Bytes.make(count*68)'\000'in
  for index=0 to count-1 do let offset=index*68 in putf vertices offset view.vertices.x.(index);putf vertices(offset+8)view.vertices.y.(index);putf vertices(offset+16)view.vertices.z.(index);(match view.normals with None->putf vertices(offset+40)1.|Some n->putf vertices(offset+24)n.x.(index);putf vertices(offset+32)n.y.(index);putf vertices(offset+40)n.z.(index));Bytes.set_int32_le vertices(offset+48)(match view.colors with None->Int32.minus_one|Some colors->let c=colors.(index)in Int32.of_int((c.r lsl 24)lor(c.g lsl 16)lor(c.b lsl 8)lor c.a))done;
  let indices=Bytes.create(Array.length view.indices*4)in Array.iteri(fun i value->Bytes.set_int32_le indices(i*4)(Int32.of_int value))view.indices;
  {pieces=result.pieces;triangles=result.triangles;render_vertices=result.render_vertices;cook_seconds=result.cook_seconds;cook_seconds_four;pack_seconds=result.pack_seconds;topology_hash=result.topology_hash;attribute_hash=result.attribute_hash;order_hash=result.order_hash;render_hash=result.render_hash;vertices;indices}
let ()=let output=ref None in Arg.parse["--output",Arg.String(fun path->output:=Some path),"artifact path"]ignore"shattered_acceptance_cook";let one=Shattered_acceptance.cook~domains:1 and four=Shattered_acceptance.cook~domains:4 in if not(Shattered_acceptance.exact one four)then failwith"one/four-domain acceptance cook mismatch";let artifact=pack one~cook_seconds_four:four.cook_seconds in let path=Option.get!output in let channel=open_out_bin path in Fun.protect~finally:(fun()->close_out channel)(fun()->Marshal.to_channel channel artifact[]);Printf.printf"pieces=%d triangles=%d render_vertices=%d topology=%s attributes=%s order=%s render=%s cook1=%.6f cook4=%.6f pack=%.6f vertex_bytes=%d index_bytes=%d\n%!"artifact.pieces artifact.triangles artifact.render_vertices artifact.topology_hash artifact.attribute_hash artifact.order_hash artifact.render_hash artifact.cook_seconds artifact.cook_seconds_four artifact.pack_seconds(Bytes.length artifact.vertices)(Bytes.length artifact.indices)
